window.receiveProjectSource({"path": "src/alembic/versions/2026_05_21_1024-5d3e923f34b8_dat_6664_add_flow_to_llm_chat_failover_.py", "lines": ["\"\"\"DAT-6664 add flow to llm_chat_failover_events", "", "Adds the ``common.failover_flow`` Postgres ENUM and a NOT NULL ``flow`` column", "on ``ai_questionnaire.llm_chat_failover_events`` so failover audit rows can", "be discriminated by pipeline flow independently of ``category_id``. The ENUM", "lives in the ``common`` schema so call sites in other services (web_extraction", "in particular) can share the type when the table itself moves to ``common``.", "Also relaxes ``category_id`` to ``NULL``-able (the FK to ``ai_prompts.categories``", "is preserved) so subsequent plans can null out entities-flow rows ahead of", "deleting the ``ENTITIES`` category fixture.", "", "ENUM members are owner-prefixed so a shared ENUM stays unambiguous:", "", "- ``aiq_global_cat`` / ``aiq_filter_cat`` / ``aiq_entities`` \u2014 AIQ flows (backfilled).", "- ``we_date_extraction`` / ``we_article_classification`` / ``we_borderline_dedup`` \u2014", "  web_extraction call-site flows, defined ahead of use so DAT-6628/DAT-6634", "  can opt those call sites into failover without a separate Alembic revision.", "  No backfill (no historic web_extraction rows exist in this table).", "", "The column is added nullable, backfilled in three passes (entities by", "matching the tombstoned ENTITIES category id, filter_cat by joining the", "failover row's (activity, category) pair into", "``ai_questionnaire.filter_model_responses``, and global_cat for everything", "else), then promoted to NOT NULL \u2014 all in this single migration.", "", "**Known backfill inconsistency (filter_cat vs global_cat):** the global-L2", "write path (``global_categories.py`` ->", "``write_filter_model_response``) also writes to ``filter_model_responses``", "with the same ``(category_id, layer_two_activity_id)`` pair the filter_cat", "backfill keys on. There is no retroactive discriminator that distinguishes", "filter-cat from global-cat writes for historical L2 failover rows, so any", "pre-migration global-L2 failover row will be labeled ``aiq_filter_cat``", "here even though runtime call sites now record those same writes as", "``FailoverFlow.AIQ_GLOBAL_CAT`` (see ``table_writes.py`` /", "``global_categories.py``). Treat the ``aiq_filter_cat`` bucket as a", "superset (filter-cat plus historical global-L2) when reading", "pre-migration audit history; rows recorded after this migration ships use", "the correct flow per call site.", "", "Plan 02 will swap the runtime ``log_observed_failover`` signature to pass", "``flow`` instead of an entities-flavored ``category``. Plan 03 will null out", "the entities ``category_id`` values and delete the ``categories.ENTITIES``", "row. Both depend on this schema being in place first.", "", "Revision ID: 5d3e923f34b8", "Revises: 54d904af0fb3", "Create Date: 2026-05-21 10:24:10.672210", "", "\"\"\"", "", "from typing import Sequence, Union", "", "import sqlalchemy as sa", "from sqlalchemy.dialects import postgresql", "", "from alembic import op", "", "# revision identifiers, used by Alembic.", "revision: str = \"5d3e923f34b8\"", "down_revision: Union[str, None] = \"54d904af0fb3\"", "branch_labels: Union[str, Sequence[str], None] = None", "depends_on: Union[str, Sequence[str], None] = None", "", "SCHEMA = \"ai_questionnaire\"", "AI_PROMPTS_SCHEMA = \"ai_prompts\"", "COMMON_SCHEMA = \"common\"", "TABLE = \"llm_chat_failover_events\"", "ENUM_NAME = \"failover_flow\"", "", "# All ENUM members. AIQ flows are backfilled below; web_extraction flows are", "# defined ahead of use (DAT-6628/DAT-6634) \u2014 no existing rows match them so", "# they participate in the type creation only. Owner-prefixed because the ENUM", "# is shared across services via the ``common`` schema.", "ENUM_VALUES = (", "    \"aiq_global_cat\",", "    \"aiq_filter_cat\",", "    \"aiq_entities\",", "    \"we_date_extraction\",", "    \"we_article_classification\",", "    \"we_borderline_dedup\",", ")", "", "", "def upgrade() -> None:", "    \"\"\"Upgrade schema.\"\"\"", "    # 1) Create the ENUM type explicitly (so add_column can reference it by name", "    # without re-creating it, and so downgrade can drop it cleanly).", "    flow_enum = sa.Enum(*ENUM_VALUES, name=ENUM_NAME, schema=COMMON_SCHEMA)", "    flow_enum.create(op.get_bind(), checkfirst=True)", "", "    # 2) Add the column as nullable so we can backfill before enforcing NOT NULL.", "    op.add_column(", "        TABLE,", "        sa.Column(", "            \"flow\",", "            sa.Enum(*ENUM_VALUES, name=ENUM_NAME, schema=COMMON_SCHEMA, create_type=False),", "            nullable=True,", "        ),", "        schema=SCHEMA,", "    )", "", "    # 3) Backfill. Order matters: entities first (most precise \u2014 match by the", "    # tombstoned ENTITIES category UUID), then filter_cat (precise \u2014 join into", "    # filter_model_responses), then global_cat as the catch-all for anything", "    # still NULL (covers true global rows AND any orphan rows whose category", "    # no longer joins anywhere \u2014 orphans default to the safer global bucket).", "    #", "    # ENTITIES_UUID is resolved at runtime via SELECT from ai_prompts.categories", "    # rather than hard-coded so the migration works across environments.", "    op.execute(", "        sa.text(", "            f\"\"\"", "            UPDATE {SCHEMA}.{TABLE} e", "            SET flow = 'aiq_entities'", "            WHERE e.category_id = (", "                SELECT id FROM {AI_PROMPTS_SCHEMA}.categories", "                WHERE name = 'ENTITIES'", "                LIMIT 1", "            )", "            \"\"\"", "        )", "    )", "", "    op.execute(", "        sa.text(", "            f\"\"\"", "            UPDATE {SCHEMA}.{TABLE} e", "            SET flow = 'aiq_filter_cat'", "            WHERE e.flow IS NULL", "              AND EXISTS (", "                  SELECT 1", "                  FROM {SCHEMA}.filter_model_responses f", "                  WHERE f.category_id = e.category_id", "                    AND f.layer_two_activity_id = e.layer_two_activity_id", "              )", "            \"\"\"", "        )", "    )", "", "    op.execute(", "        sa.text(", "            f\"\"\"", "            UPDATE {SCHEMA}.{TABLE}", "            SET flow = 'aiq_global_cat'", "            WHERE flow IS NULL", "            \"\"\"", "        )", "    )", "", "    # 4) Promote flow to NOT NULL now that every existing row has a value.", "    op.alter_column(", "        TABLE,", "        \"flow\",", "        existing_type=sa.Enum(", "            *ENUM_VALUES, name=ENUM_NAME, schema=COMMON_SCHEMA, create_type=False", "        ),", "        nullable=False,", "        schema=SCHEMA,", "    )", "", "    # 5) Relax category_id to nullable so Plan 03 can null out entities rows", "    # before the categories.ENTITIES fixture row is removed. The FK constraint", "    # to ai_prompts.categories.id remains in place.", "    op.alter_column(", "        TABLE,", "        \"category_id\",", "        existing_type=postgresql.UUID(),", "        nullable=True,", "        schema=SCHEMA,", "    )", "", "", "def downgrade() -> None:", "    \"\"\"Downgrade schema.\"\"\"", "    # Re-impose NOT NULL on category_id. If Plan 03 has already nulled out", "    # entities rows in this environment, this statement will fail \u2014 that is", "    # acceptable; the downgrade target is the pre-Plan-03 state.", "    op.alter_column(", "        TABLE,", "        \"category_id\",", "        existing_type=postgresql.UUID(),", "        nullable=False,", "        schema=SCHEMA,", "    )", "", "    op.drop_column(TABLE, \"flow\", schema=SCHEMA)", "", "    sa.Enum(", "        name=ENUM_NAME,", "        schema=COMMON_SCHEMA,", "    ).drop(op.get_bind(), checkfirst=True)"], "blocks": [{"start": 1, "end": 83, "label": "Imports and module setup"}, {"start": 84, "end": 172, "label": "def upgrade"}, {"start": 173, "end": 191, "label": "def downgrade"}], "lineCount": 191, "sha256": "09e115094944bbdb1cb4a11e7a4913197d4ca3bdc11f2d633dc1e8b4b592752d", "endsWithNewline": true});
